import type { Plugin, Resource } from "@dylanebert/shallot";
import {
    lit,
    MaterialPlugin,
    type MaterialHandle,
    materialType,
} from "@dylanebert/shallot/standard/rendering";
import * as d from "typegpu/data";
import * as std from "typegpu/std";

/** Diagonal bands per face, and how many bands pass a point per second. */
export const STRIPE_COUNT = 5;
export const STRIPE_SPEED = 0.6;

export const StripeParameters = d.struct({
    time: d.f32,
    colorA: d.vec3f,
    colorB: d.vec3f,
});

/** Diagonal stripes across each face's UVs, scrolling with the material's own time. */
export const StripeMaterial = materialType({
    name: "MovingStripes",
    parameters: StripeParameters,
    defaults: { time: 0, colorA: d.vec3f(0.04, 0.035, 0.03), colorB: d.vec3f(0.72, 0.4, 0.05) },
    fragmentInputs: { uv: true },
    fragment: (ctx) => {
        "use gpu";
        const phase = (ctx.uv.x + ctx.uv.y) * STRIPE_COUNT - ctx.parameters.time * STRIPE_SPEED;
        const band = std.fract(phase);
        // Soft-edged bands: a crisp line with a little antialiasing width.
        const value = std.smoothstep(0.45, 0.5, band) - std.smoothstep(0.95, 1, band);
        const color = std.mix(ctx.parameters.colorA, ctx.parameters.colorB, value);
        return d.vec4f(lit(color, ctx.worldNormal), 1);
    },
});

export const Stripes: Resource<{ handle?: MaterialHandle; time: number }> = {
    create: () => ({ time: 0 }),
};

export const StripesPlugin: Plugin = {
    name: "Stripes",
    dependencies: [MaterialPlugin(StripeMaterial)],
    initialize(world) {
        world.resource(Stripes).handle = world.resource(StripeMaterial).add({
            time: 0,
            colorA: d.vec3f(0.04, 0.035, 0.03),
            colorB: d.vec3f(0.72, 0.4, 0.05),
        });
    },
    systems: [
        {
            name: "Stripes/Animate",
            update(world) {
                const stripes = world.resource(Stripes);
                stripes.time += world.time.deltaTime;
                world.resource(StripeMaterial).update(stripes.handle!, { time: stripes.time });
            },
        },
    ],
};

