import {
    Camera,
    component,
    DirectionalLight,
    GlobalAmbientLight,
    lookAtRotation,
    Materials,
    MeshInstance,
    MeshMaterial,
    type Plugin,
    StandardMaterial,
    StandardRenderer,
    Transform,
    type World,
} from "@dylanebert/shallot";
import { Orbit, OrbitPlugin } from "@dylanebert/shallot/extras";
import { Stripes, StripesPlugin } from "./stripes";

export const WelcomeCube = component("WelcomeCube", {});

function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xd8e4ff;
    ambient.brightness = 380;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xffe8cc, illuminance: 6000 });
    world.storage(DirectionalLight).shadowMapsEnabled.set(sun, 1);

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 6, yaw: 0.7, pitch: 0.4 });
    world.add(camera, Transform);

    const cube = world.create();
    world.add(cube, MeshInstance);
    world.add(cube, MeshMaterial, world.resource(Stripes).handle!);
    world.add(cube, Transform, { translation: [0, 0, 0] });
    world.add(cube, WelcomeCube);

    const groundMaterial = world.resource(Materials).add(
        StandardMaterial({
            baseColor: [0.085, 0.08, 0.072, 1],
            perceptualRoughness: 0.82,
        }),
    );
    const ground = world.create();
    world.add(ground, MeshInstance);
    world.add(ground, MeshMaterial, groundMaterial);
    world.add(ground, Transform, {
        translation: [0, -0.6, 0],
        scale: [4, 0.2, 4],
    });
}

export const Welcome: Plugin = {
    name: "Welcome",
    components: [WelcomeCube],
    dependencies: [OrbitPlugin, StripesPlugin],
    initialize: makeScene,
};

import { expect, setDefaultTimeout, test } from "bun:test";
import { attachTexture, Camera, captureTexture } from "@dylanebert/shallot/rendering";
import { TIMEOUT } from "@dylanebert/shallot/testing";
import { openGpuApp } from "@dylanebert/shallot/testing/gpu";
import { Welcome } from "../src/welcome";

setDefaultTimeout(TIMEOUT.node);

const SIZE = 96;

function luminanceRow(rgba: Uint8Array, y: number, x0: number, x1: number): number[] {
    const row: number[] = [];
    for (let x = x0; x < x1; x++) {
        const o = (y * SIZE + x) * 4;
        row.push(rgba[o]! + rgba[o + 1]! + rgba[o + 2]!);
    }
    return row;
}

test("the cube shows bands that shift as time passes", async () => {
    const app = await openGpuApp({ defaults: false, plugins: [Welcome] });
    try {
        const { world } = app;
        const camera = [...world.query([Camera])][0]!;
        attachTexture(world, camera, { width: SIZE, height: SIZE });
        world.step(0);
        world.step(0);
        const first = (await captureTexture(world, camera)).rgba;
        for (let i = 0; i < 30; i++) world.step(1 / 60);
        const later = (await captureTexture(world, camera)).rgba;

        // Centre of the frame is the cube: bands mean strong light/dark alternation.
        let alternations = 0;
        for (let y = 38; y < 58; y += 4) {
            const row = luminanceRow(first, y, 30, 66);
            const mid = (Math.max(...row) + Math.min(...row)) / 2;
            for (let i = 1; i < row.length; i++)
                if (row[i - 1]! < mid !== row[i]! < mid && Math.max(...row) - Math.min(...row) > 60)
                    alternations++;
        }
        expect(alternations, "visible band edges on the cube").toBeGreaterThan(8);

        let changed = 0;
        for (let y = 30; y < 66; y++)
            for (let x = 30; x < 66; x++) {
                const o = (y * SIZE + x) * 4;
                if (Math.abs(first[o]! - later[o]!) > 30) changed++;
            }
        expect(changed, "pixels on the cube that changed as the bands moved").toBeGreaterThan(100);
    } finally {
        app.dispose();
    }
});

